from matplotlib.patches import Rectangle, FancyArrowPatch
fig = plt.gcf(); fig.set_size_inches(6.4, 3.8); ax = plt.gca()
heads = ['thousands', 'hundreds', 'tens', 'ones']
w = 1.5; x0 = 0.6
for c, hd in enumerate(heads):
    ax.text(x0 + c * w + w / 2, 4.25, hd, ha='center', va='center', fontsize=10)
rows = [(3.0, ['3', '9', '9', '5'], ''), (2.0, ['', '', '1', '0'], '+'), (0.6, ['4', '0', '0', '5'], '')]
for y, digs, sign in rows:
    for c, d in enumerate(digs):
        ax.add_patch(Rectangle((x0 + c * w, y), w, 0.9, fill=False, ec='black', lw=1.0))
        if d:
            ax.text(x0 + c * w + w / 2, y + 0.45, d, ha='center', va='center', fontsize=17, color='blue' if (y < 1 and c < 3) else 'black')
    if sign:
        ax.text(x0 - 0.3, y + 0.45, sign, ha='center', va='center', fontsize=17)
ax.plot([x0, x0 + 4 * w], [1.8, 1.8], color='black', lw=1.6)
notes = ['3+1 = 4', '9+1 = 10', '9+1 = 10', '5+0 = 5']
for c, t in enumerate(notes):
    ax.text(x0 + c * w + w / 2, 0.35, t, ha='center', va='center', fontsize=10, color='red' if c < 3 else 'black')
for c in (2, 1):
    ax.add_patch(FancyArrowPatch((x0 + c * w + w / 2, 0.12), (x0 + (c - 1) * w + w / 2, 0.12), connectionstyle='arc3,rad=-0.45', arrowstyle='-|>', mutation_scale=12, color='red', lw=1.1))
    ax.text(x0 + c * w, -0.45, 'carry 1', ha='center', va='center', fontsize=9, color='red')
ax.text(x0 + 4 * w + 0.2, 0.75, '3,995 + 10\n= 4,005', ha='left', va='center', fontsize=11)
ax.set_xlim(-0.1, 9.6); ax.set_ylim(-0.8, 4.5); ax.set_aspect('equal'); ax.axis('off')
